'use strict';
const KEY='yasbe-tm-demo-v3', SIZE=5;
const PEOPLE={'初审甲':'初审','运营乙':'初审','合规甲':'合规','合规乙':'合规','管理员':'管理员'};
let ME=localStorage.getItem('tm-actor')||'初审甲';if(!PEOPLE[ME])ME='初审甲';
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const biz={Crypto:'Crypto Wallet',Bank:'VA · OpenPayd',Card:'YASBe Card'};
const names=['链上入金','链上出金','VA 入金','VA 出金','Card 充值','Card 转出到 Crypto Wallet'];
const now=()=>new Date().toLocaleString('sv-SE',{hour12:false});
function seed(){
 const transactions=[];let n=0;
 function add(uid,b,event,amount,currency,date,caseId='',send='已上送'){const id='TX-DEMO-'+String(++n).padStart(4,'0');transactions.push({id,uid,biz:b,event,amount,currency,date,caseId,send,business:'成功',tries:send==='上送失败'?1:0,error:send==='上送失败'?'连接超时；尚未取得 CA 受理结果':'',receipt:send==='已上送'?'CA-DEMO-'+n:'',logs:[],base:'暂未获取',network:b==='Crypto'?'Ethereum':'不适用'});return id;}
 const cases=[];
 function make(id,uid,b,rule,state,owner,count,day){let ids=[];for(let j=0;j<count;j++)ids.push(add(uid,b,b==='Bank'?'VA 入金':'链上入金',String(1000+j*500),b==='Bank'?'EUR':'USDT',`2026-11-${day} ${String(9+j).padStart(2,'0')}:00:00`,id));cases.push({id,uid,biz:b,rule,state,owner,created:`2026-11-${day} 13:00:00`,ids,actual:count+' 笔',threshold:'> 3 笔',window:`2026-11-${Number(day)-6} 00:00 — 2026-11-${day} 23:59`,direction:'入金',sync:'暂无提交',draft:'',conclusion:'',logs:[],records:[],priority:'P7 · Low',source:'4. Scenarios · '+(b==='Bank'?'第 10 行':'第 12 行')});}
 make('CASE-DEMO-001','U-DEMO-1001','Crypto','RL_0015','未开始','',4,19);
 make('CASE-DEMO-002','U-DEMO-1002','Bank','RL_0015','调查中','初审甲',4,18);
 const card='CASE-DEMO-003';const cardIds=[add('U-DEMO-1003','Card','Card 充值','1000','USD','2026-11-19 10:00:00',card),add('U-DEMO-1003','Card','Card 转出到 Crypto Wallet','950','USD','2026-11-19 10:08:00',card)];
 cases.push({id:card,uid:'U-DEMO-1003',biz:'Card',rule:'Card 快速转出（待确认）',state:'未开始',owner:'',created:'2026-11-19 10:09:00',ids:cardIds,actual:'充值后 8 分钟发生转出',threshold:'待确认',window:'待确认',direction:'充值 → 转出',sync:'暂无提交',draft:'',conclusion:'',logs:[],records:[],priority:'待确认',source:'产品拟议场景，非 CA 已配置命中'});
 make('CASE-DEMO-004','U-DEMO-1004','Bank','RL_0015','已结案','初审甲',4,17);
 cases[3].conclusion='接受并结案';cases[3].sync='提交成功';cases[3].records.push({time:'2026-11-18 11:00:00',actor:'初审甲',text:'客户交易用途经核对一致，演示结案记录。',conclusion:'接受并结案'});
 make('CASE-DEMO-005','U-DEMO-1005','Crypto','RL_0015','待合规接收','初审甲',4,16);
 make('CASE-DEMO-006','U-DEMO-1006','Bank','RL_0015','调查中','运营乙',4,15);
 make('CASE-DEMO-007','U-DEMO-1007','Crypto','RL_0015','未开始','',4,14);
 cases[4].conclusion='升级调查';cases[4].sync='提交成功';cases[4].records.push({time:'2026-11-17 11:00:00',actor:'初审甲',text:'交易用途需进一步核查，演示升级记录。',conclusion:cases[4].conclusion});
 add('U-DEMO-1008','Crypto','链上出金','2500','USDC','2026-11-19 14:20:00','','上送失败');
 add('U-DEMO-1009','Bank','VA 出金','680','GBP','2026-11-19 15:00:00','','待上送');
 add('U-DEMO-1010','Card','Card 充值','800','USD','2026-11-19 15:10:00');
 transactions.forEach((t,i)=>{t.evaluation=t.send==='已上送'?(i===transactions.length-1?'PENDING':'ALLOW'):'暂未获取';t.relation='CONTEXTUAL';t.freshness='UP_TO_DATE';});cases.forEach(c=>{const t=transactions.find(t=>t.id===c.ids[c.ids.length-1]);if(t)t.relation='ALERTING';});cases.forEach(c=>{c.initialOwner=c.owner||'';c.reviewer='';c.supervised=c.state==='待合规接收';if(c.supervised){c.owner='';c.queue='合规';}else c.queue='初审';});return {version:3,cases,transactions};
}
let db;try{db=JSON.parse(localStorage.getItem(KEY));}catch(e){}if(!db||db.version!==3)db=seed();
db.cases.forEach(c=>{if(c.pending&&c.sync==='提交中')c.sync='提交失败';});
const save=()=>localStorage.setItem(KEY,JSON.stringify(db));
const badge=v=>`<span class="badge ${['已结案','已上送','成功','提交成功'].includes(v)?'green':['上送失败','提交失败','待合规接收'].includes(v)?'red':['调查中','上送中','提交中'].includes(v)?'blue':'amber'}">${esc(v)}</span>`;
const options=(vals,all='全部')=>`<option value="">${all}</option>`+vals.map(v=>`<option value="${esc(v)}">${esc(biz[v]||v)}</option>`).join('');
const getCase=id=>db.cases.find(c=>c.id===id);
let page=1,filtered=[],activeCase=null,focusBefore=null,toastTimer;
function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',2600);}
function modal(title,body,buttons=''){focusBefore=document.activeElement;$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalFoot').innerHTML=buttons||'<button data-action="close">关闭</button>';$('overlay').classList.add('active');$('modalClose').focus();}
function closeModal(){$('overlay').classList.remove('active');if(focusBefore?.isConnected)focusBefore.focus();}
function log(c,text){c.logs.unshift({time:now(),actor:ME,text});}
function shell(){const p=document.body.dataset.page;const menu=[['index.html','总览','index'],['2026-11-19_案件列表_管理端.html','案件列表','cases'],['2026-11-19_监控交易记录_管理端.html','监控交易记录','transactions']];$('app').innerHTML=`<aside class="sidebar"><div class="logo">YAS<span>Be</span></div><div class="nav-label">管理端 / 风控管理</div>${menu.map(([h,t,k])=>`<a href="${h}" class="${p===k||(p==='detail'&&k==='cases')?'active':''}">${t}</a>`).join('')}<div class="side-foot">交易监控<br>CA / Mesh TM<br><br>案件闭环评审 · v0.3</div></aside><main><header class="topbar"><span>风控管理 / 交易监控</span><span><b>${ME}</b> · ${PEOPLE[ME]}</span></header><div id="content"></div><details class="demo"><summary>[原型演示] 控制区 · 所有数据均为虚构样例</summary><div class="demo-box"><label>演示身份<select id="actor">${Object.keys(PEOPLE).map(n=>`<option ${n===ME?'selected':''}>${n}</option>`).join('')}</select></label><label class="check"><input type="checkbox" id="failNext">下次 CA 提交模拟失败</label><button data-action="reset-demo">重置演示数据</button><span>本地浏览器保存，不连接 CA 或真实资金系统。</span></div></details></main><div id="toast" role="status" aria-live="polite"></div><div class="modal-overlay" id="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><h2 id="modalTitle"></h2><button id="modalClose" data-action="close" aria-label="关闭弹窗">×</button></div><div class="modal-body" id="modalBody"></div><div class="modal-foot" id="modalFoot"></div></section></div>`;}
function stats(items){return '<div class="stats">'+items.map(([t,v,s])=>`<div class="stat"><span>${t}</span><strong>${v}</strong><small>${s}</small></div>`).join('')+'</div>';}
function indexPage(){$('content').innerHTML=`<div class="heading"><div><h1>交易监控</h1><p class="sub">成功交易入监控，案件调查有依据。</p></div><span class="badge amber">首版评审</span></div><div class="pmnote">[PM 备注] 业务范围已回查原话；状态按 CA 工作流展示，当前阶段为演示配置；Card 快速转出规则仍待确认。</div><div class="cards"><article class="entry"><div class="num">01</div><h2>案件列表</h2><p>查看命中案件、领取未分配工作，按业务、负责人和规则定位案件。</p><a class="btn primary" href="2026-11-19_案件列表_管理端.html">进入案件列表 →</a></article><article class="entry"><div class="num">02</div><h2>案件详情</h2><p>查看命中原因与关联交易，保存调查草稿、向 CA 提交阶段变更并核对结果。</p><a class="btn" href="2026-11-19_案件详情_管理端.html?id=CASE-DEMO-001">查看笔数告警 →</a><br><a href="2026-11-19_案件详情_管理端.html?id=CASE-DEMO-003">查看 Card 资金时间线</a></article><article class="entry"><div class="num">03</div><h2>监控交易记录</h2><p>覆盖全部纳入范围的交易；业务成功状态与 CA 上送状态分别展示。</p><a class="btn" href="2026-11-19_监控交易记录_管理端.html">查看交易记录 →</a></article></div><section class="panel"><h2>本期监控范围</h2><dl class="kv"><div><dt>Crypto Wallet</dt><dd>成功链上入金、成功链上出金<br><span class="sub">监控金额与笔数</span></dd></div><div><dt>VA · OpenPayd EUR / GBP</dt><dd>成功入金、成功出金<br><span class="sub">监控金额与笔数</span></dd></div><div><dt>YASBe Card</dt><dd>充值、转出到 Crypto Wallet<br><span class="sub">关注充值后快速转出，判定口径待确认</span></dd></div></dl></section><section class="panel"><h2>需求与规则依据</h2><p><a href="../../prd/交易监控/交易监控-PRD.md">打开需求文档</a></p><p class="sub">新版金额／笔数规则按客户＋业务类型统计；跨业务交易不混算，跨币种金额不直接相加。</p><p class="sub">已成功交易不提供放行／拒绝按钮。Card 消费、开卡、拒付、ATM 不在本期范围。</p></section>`;}
function casePage(){$('content').innerHTML=`<div class="heading"><div><h1>案件列表</h1><p class="sub">查看、领取并调查交易监控案件。</p></div><a class="btn" href="2026-11-19_监控交易记录_管理端.html">监控交易记录</a></div><div class="pmnote">[原型演示] 虚构案件；7 天 &gt; 3 笔来自表内配置示例，尚未作为生产阈值确认。</div>${stats([['全部案件',db.cases.length,'当前演示数据'],['我的待办',db.cases.filter(c=>c.owner===ME&&c.state!=='已结案').length,'当前身份负责'],['合规待接收',db.cases.filter(c=>c.state==='待合规接收').length,'合规人员接收后复核'],['已结案',db.cases.filter(c=>c.state==='已结案').length,'CA 已确认结束阶段']])}<form id="filters" class="filters"><label class="wide">Case ID / 客户 UID<input id="q" placeholder="输入案件号或客户 UID"></label><label>业务<select id="biz">${options(Object.keys(biz))}</select></label><label>案件状态<select id="state">${options(['未开始','调查中','待合规接收','合规复核中','待补充','已结案'],'未开始（默认）')}</select></label><label>工作队列<select id="queue">${options(['我的待办','初审待领取','合规待接收'])}</select></label><label>负责人<select id="owner">${options(['未分配',...Object.keys(PEOPLE)])}</select></label><label>命中规则<select id="rule">${options(['RL_0015','Card 快速转出（待确认）'])}</select></label><label>创建起始日期<input id="from" type="date"></label><label>创建结束日期<input id="to" type="date"></label><button class="primary" type="submit">查询</button><button type="button" data-action="clear">重置</button></form><div class="error" id="filterError"></div><section class="panel table-panel"><div class="table-title"><h2>案件明细</h2><button class="link" data-action="all-cases">查看全部案件</button></div><div class="table-wrap"><table><thead><tr><th>Case ID / 客户 UID</th><th>涉及业务</th><th>命中规则</th><th>关联交易</th><th>状态</th><th>负责人</th><th>创建时间</th><th>操作</th></tr></thead><tbody id="rows"></tbody></table></div><div id="pager" class="pager"></div></section>`;
 $('state').options[0].text='全部';$('state').value='';bindFilters();renderCases();}
function bindFilters(){$('filters').onsubmit=e=>{e.preventDefault();page=1;renderList();};}
function validDate(){const bad=$('from').value&&$('to').value&&$('from').value>$('to').value;$('filterError').textContent=bad?'开始日期不能晚于结束日期。':'';return !bad;}
function matchCommon(x){let q=$('q').value.trim().toLowerCase();return (!q||(x.id+' '+x.uid).toLowerCase().includes(q))&&(!$('biz').value||x.biz===$('biz').value)&&(!$('from').value||(x.created||x.date).slice(0,10)>=$('from').value)&&(!$('to').value||(x.created||x.date).slice(0,10)<=$('to').value);}
function renderCases(){if(!validDate())return;filtered=db.cases.filter(c=>matchCommon(c)&&(!$('queue').value||($('queue').value==='我的待办'?c.owner===ME&&c.state!=='已结案':$('queue').value==='初审待领取'?c.state==='未开始'&&!c.owner:c.state==='待合规接收'))&&(!$('state').value||c.state===$('state').value)&&(!$('owner').value||($('owner').value==='未分配'?!c.owner:c.owner===$('owner').value))&&(!$('rule').value||c.rule===$('rule').value));page=Math.max(1,Math.min(page,Math.ceil(filtered.length/SIZE)));$('rows').innerHTML=filtered.slice((page-1)*SIZE,page*SIZE).map(c=>`<tr><td><a class="mono" href="2026-11-19_案件详情_管理端.html?id=${c.id}">${c.id}</a><p class="sub">${c.uid}</p></td><td>${biz[c.biz]}</td><td class="wrap">${esc(c.rule)}<p class="sub">${c.biz==='Card'?'待确认场景':'7 天入金笔数'}</p></td><td>${c.ids.length} 笔</td><td>${badge(c.state)}</td><td>${c.owner||'未分配'}</td><td>${c.created}</td><td><div class="actions"><a href="2026-11-19_案件详情_管理端.html?id=${c.id}">查看</a>${allowed(c,'claim')?`<button class="link" data-action="claim" data-id="${c.id}">领取</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="8" class="empty">没有符合条件的案件，请调整筛选条件。</td></tr>';pager();}
function pager(){const total=Math.max(1,Math.ceil(filtered.length/SIZE));$('pager').innerHTML=`<span class="count">共 ${filtered.length} 条 · 每页 ${SIZE} 条</span><button data-action="prev" ${page<=1?'disabled':''}>上一页</button><span>${page} / ${total}</span><button data-action="next" ${page>=total?'disabled':''}>下一页</button>`;}
function renderList(){if(document.body.dataset.page==='cases')renderCases();else renderTransactions();}
function claim(id){const c=getCase(id);if(allowed(c,'claim'))flowDialog(c,'claim');}
function confirmClaim(id){const c=getCase(id);if(allowed(c,'claim'))flowDialog(c,'claim');}
function txTable(ids){const ts=ids.map(id=>db.transactions.find(t=>t.id===id)).filter(Boolean);return `<div class="table-wrap"><table><thead><tr><th>交易时间</th><th>业务 / 事件</th><th>原始金额</th><th>业务状态 / 关联类型 / 证据版本</th><th>平台交易号</th><th>操作</th></tr></thead><tbody>${ts.map(t=>`<tr><td>${t.date}</td><td>${biz[t.biz]}<p class="sub">${t.event}</p></td><td>${t.amount} ${t.currency}</td><td>${badge(t.business)}<p class="sub">${t.relation==='ALERTING'?'触发交易':'上下文交易'} · ${t.freshness}</p></td><td class="mono">${t.id}</td><td><button class="link" data-action="tx" data-id="${t.id}">查看交易</button></td></tr>`).join('')}</tbody></table></div>`;}
function detailPage(){const id=new URLSearchParams(location.search).get('id')||'CASE-DEMO-001';const c=getCase(id);activeCase=c;if(!c){$('content').innerHTML='<section class="panel"><h1>未找到该案件</h1><p>请核对案件编号。</p><a href="2026-11-19_案件列表_管理端.html">返回案件列表</a></section>';return;}const can=canEdit(c);$('content').innerHTML=`<a href="2026-11-19_案件列表_管理端.html">← 返回案件列表</a><div class="heading"><div><h1>${c.id} ${badge(c.state)}</h1><p class="sub">${biz[c.biz]} · ${c.uid}</p></div><div class="actions">${flowButtons(c)}<a class="btn" href="2026-11-19_监控交易记录_管理端.html?uid=${c.uid}">客户监控交易</a></div></div><div class="pmnote">[原型演示] ${c.biz==='Card'?'Card 资金时间线为拟议样例，不是已配置 CA 案件；映射与规则确认前不开放案件处理。':'虚构 CA 案件、告警与风险样例；阶段选项演示账户工作流，生产需读取实际阶段标识与权限。'}</div>${flowPanel(c)}<section class="panel"><h2>案件概况</h2><p class="sub">案件阶段取自 CA；领取只更新负责人。当前示例阶段不是账户生产配置。</p><dl class="kv"><div><dt>客户 UID</dt><dd>${c.uid}</dd></div><div><dt>负责人</dt><dd>${c.owner||'未分配'}</dd></div><div><dt>创建时间</dt><dd>${c.created}</dd></div><div><dt>告警优先级</dt><dd>${c.priority}</dd></div><div><dt>处理结论</dt><dd>${esc(c.conclusion||'尚未提交')}</dd></div><div><dt>CA 操作结果</dt><dd id="sync">${badge(c.sync)} ${c.sync==='提交失败'&&c.pending&&(c.pending.actor===ME||PEOPLE[ME]==='管理员')?`<button class="link" data-action="sync-retry">核查并重试</button>`:''}</dd></div></dl>${c.sync==='提交失败'?'<p class="error">提交未确认，案件仍保持 CA 最后确认的负责人及阶段。草稿和本次请求已保留，核查后重试。</p>':''}</section><section class="panel"><h2>命中原因与证据</h2><div class="rule"><p class="sub">${c.biz==='Card'?'拟议场景：没有已确认的 CA 风险标识':'告警 DEMO-ALERT-'+c.id+' · 风险 DEMO-RISK-'+c.id+' · 说明来自风险 observation（演示）'}</p><h3>${c.biz==='Card'?'充值后快速转出 · 拟议场景':c.rule+' · 7 天入金笔数'}</h3><dl class="kv"><div><dt>统计对象</dt><dd>${c.uid} + ${c.biz}</dd></div><div><dt>资金方向</dt><dd>${c.direction}</dd></div><div><dt>触发阈值</dt><dd>${esc(c.threshold)}</dd></div><div><dt>实际值</dt><dd>${esc(c.actual)}</dd></div><div><dt>统计窗口</dt><dd>${c.window}</dd></div><div><dt>规则依据</dt><dd>${c.source}</dd></div></dl></div><p class="sub">${c.biz==='Card'?'充值与转出的配对方式、成功节点、时间窗和比例阈值尚待确认。':'按客户＋业务类型独立统计。表内 Outcome = Allow 不代表本平台自动放行；当前交易已成功。'}</p></section><section class="panel table-panel"><div class="table-title"><h2>关联交易 · ${c.ids.length} 笔</h2><span class="sub">原币分别展示，不跨币种汇总</span></div>${txTable(c.ids)}</section>${c.biz==='Card'?`<section class="panel"><h2>Card 资金时间线</h2><div class="timeline">${c.ids.map(id=>db.transactions.find(t=>t.id===id)).map(t=>`<div class="event"><time>${t.date}</time><p>${t.event} · ${t.amount} ${t.currency}</p><p class="sub">${t.id}</p></div>`).join('')}</div><p class="notice">两笔样例相隔 8 分钟；未计算转出比例。卡账户记账币种与钱包到账币种需分别保留，不能把 USD 金额直接当作 USDT 数量。</p></section>`:''}<div class="grid"><section class="panel"><h2>调查处理</h2><p class="sub">${nextStep(c)}</p><label>调查说明<textarea id="note" ${can?'':'disabled'} placeholder="说明核查内容、交易用途及判断依据">${esc(c.draft)}</textarea></label><label>目标阶段<select id="conclusion" ${can?'':'disabled'}>${options(decisions(c),'请选择处理结果')}</select></label><div class="error" id="formError"></div><div class="footer-actions"><button data-action="draft" ${can?'':'disabled'}>保存草稿</button><button class="primary" data-action="submit" ${can?'':'disabled'}>提交处理</button></div><p class="sub">提交确认后更新阶段及归属；待合规接收进入公共合规队列。处理案件不改变交易或资金状态。</p></section><section class="panel"><h2>调查记录</h2>${c.records.length?c.records.map(r=>`<div class="event"><p>${badge(r.conclusion)} · ${r.actor}</p><time>${r.time}</time><p>${esc(r.text)}</p></div>`).join(''):'<p class="sub">尚无已提交的调查记录。</p>'}</section></div><section class="panel"><h2>操作日志</h2>${c.logs.length?`<ol class="audit">${c.logs.map(l=>`<li>${l.time} · ${l.actor} · ${esc(l.text)}</li>`).join('')}</ol>`:'<p class="sub">暂无本地操作。</p>'}</section>`;}
function draft(){const c=activeCase;if(!canEdit(c))return;c.draft=$('note').value;log(c,'保存调查草稿');save();toast('草稿已保存');}
function submit(){const c=activeCase;if(!canEdit(c))return;const v=$('conclusion').value,text=$('note').value.trim();if(!decisions(c).includes(v)||!text){$('formError').textContent='请填写调查说明并选择处理结果。';return;}flowDialog(c,v,text);}
function finishSubmit(){confirmFlow();}
function failNext(){const f=$('failNext').checked;$('failNext').checked=false;return f;}
function runSync(c){if(!c?.pending||c.sync==='提交中'||(c.pending.actor!==ME&&PEOPLE[ME]!=='管理员'))return;const req=c.pending,fail=failNext();c.sync='提交中';save();refreshFlow();setTimeout(()=>{if(c.pending!==req)return;if(fail){c.sync='提交失败';c.logs.unshift({time:now(),actor:req.actor,text:'操作未确认：'+req.action+'；保留原阶段和负责人'});}else{const before=c.state+' / '+(c.owner||c.queue+'队列');Object.assign(c,req.patch);if(req.text)c.records.unshift({time:now(),actor:req.actor,text:req.text,conclusion:req.action});c.logs.unshift({time:now(),actor:req.actor,text:req.action+'：'+before+' → '+c.state+' / '+(c.owner||c.queue+'队列')});c.pending=null;c.sync='提交成功';}save();refreshFlow();toast(fail?'操作未确认，原处理人和阶段保留':'操作已确认（原型演示）');},650);}
function transactionPage(){$('content').innerHTML=`<div class="heading"><div><h1>监控交易记录</h1><p class="sub">核对纳入监控的交易及 CA 上送结果，包含未产生案件的交易。</p></div><a class="btn" href="2026-11-19_案件列表_管理端.html">案件列表</a></div><div class="pmnote">[原型演示] Card 暂以成功事件演示，正式成功节点待确认；Card → Wallet 不重复记作链上入金。</div><div id="txStats"></div><form id="filters" class="filters"><label class="wide">客户 UID / 平台交易号<input id="q" placeholder="输入客户 UID 或平台交易号"></label><label>业务<select id="biz">${options(Object.keys(biz))}</select></label><label>交易事件<select id="event">${options(names)}</select></label><label>CA 上送状态<select id="send">${options(['待上送','上送中','已上送','上送失败'])}</select></label><label>成功起始日期<input id="from" type="date"></label><label>成功结束日期<input id="to" type="date"></label><button class="primary" type="submit">查询</button><button type="button" data-action="clear">重置</button></form><div class="error" id="filterError"></div><section class="panel table-panel"><div class="table-title"><h2>交易明细</h2><span class="sub">业务成功、CA 受理与评估结果分别核对</span></div><div class="table-wrap"><table><thead><tr><th>成功时间 / 平台交易号</th><th>客户 UID</th><th>业务 / 事件</th><th>原始金额</th><th>交易状态</th><th>CA 上送 / 评估结果</th><th>关联 Case</th><th>操作</th></tr></thead><tbody id="rows"></tbody></table></div><div class="pager" id="pager"></div></section>`;$('q').value=new URLSearchParams(location.search).get('uid')||'';bindFilters();renderTransactions();}
function renderTransactions(){if(!validDate())return;$('txStats').innerHTML=stats([['纳入监控',db.transactions.length,'当前演示数据 · 不受筛选影响'],['已上送',db.transactions.filter(t=>t.send==='已上送').length,'CA 已受理，评估可能尚未完成'],['待上送',db.transactions.filter(t=>t.send==='待上送'||t.send==='上送中').length,'等待受理'],['上送失败',db.transactions.filter(t=>t.send==='上送失败').length,'核查后可补送']]);filtered=db.transactions.filter(t=>matchCommon(t)&&(!$('event').value||t.event===$('event').value)&&(!$('send').value||t.send===$('send').value)).sort((a,b)=>b.date.localeCompare(a.date));page=Math.max(1,Math.min(page,Math.ceil(filtered.length/SIZE)));$('rows').innerHTML=filtered.slice((page-1)*SIZE,page*SIZE).map(t=>`<tr><td>${t.date}<p class="sub mono">${t.id}</p></td><td>${t.uid}</td><td>${biz[t.biz]}<p class="sub">${t.event}</p></td><td>${t.amount} ${t.currency}</td><td>${badge(t.business)}</td><td>${badge(t.send)}<p class="sub">${esc(t.evaluation)}</p></td><td>${t.caseId?`<a href="2026-11-19_案件详情_管理端.html?id=${t.caseId}">${t.caseId}</a>`:'—'}</td><td><div class="actions"><button class="link" data-action="tx" data-id="${t.id}">详情</button>${t.send==='上送失败'?`<button class="link" data-action="resend" data-id="${t.id}">补送</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="8" class="empty">没有符合条件的交易，请调整筛选条件。</td></tr>';pager();}
function txDetail(id){const t=db.transactions.find(t=>t.id===id);if(!t)return;modal('交易详情',`<dl class="kv"><div><dt>平台交易号</dt><dd class="mono">${t.id}</dd></div><div><dt>客户 UID</dt><dd>${t.uid}</dd></div><div><dt>业务</dt><dd>${biz[t.biz]}</dd></div><div><dt>交易事件</dt><dd>${t.event}</dd></div><div><dt>成功时间</dt><dd>${t.date}</dd></div><div><dt>原始金额 / 币种</dt><dd>${t.amount} ${t.currency}</dd></div><div><dt>折算金额 / 币种</dt><dd>${t.base}</dd></div><div><dt>网络</dt><dd>${t.network}</dd></div><div><dt>业务状态</dt><dd>${badge(t.business)}</dd></div><div><dt>CA 上送状态</dt><dd>${badge(t.send)}</dd></div><div><dt>CA 交易标识（查询结果）</dt><dd>${t.receipt||'暂未获取'}</dd></div><div><dt>CA 评估结果</dt><dd>${esc(t.evaluation)}</dd></div><div><dt>补送次数</dt><dd>${t.logs.filter(l=>l.includes('补送完成')).length}</dd></div></dl>${t.error?`<p class="error">${esc(t.error)}</p>`:''}<p class="notice">原始金额与折算金额分开保留。未提供折算依据时不进行跨币种合计。</p><h3 style="margin-top:20px">上送操作记录</h3>${t.logs.length?`<ul class="audit">${t.logs.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>`:'<p class="sub">暂无补送记录。</p>'}`,`<button data-action="close">关闭</button>${t.send==='已上送'&&t.evaluation==='PENDING'?`<button data-action="evaluation" data-id="${t.id}">刷新评估结果</button>`:''}${t.send==='上送失败'?`<button class="primary" data-action="resend" data-id="${t.id}">核查并补送</button>`:''}`);}
function resend(id){const t=db.transactions.find(t=>t.id===id);if(!t||t.send!=='上送失败')return;modal('核查上送结果',`<p>交易：<span class="mono">${t.id}</span></p><p class="sub">超时不等于 CA 未受理。先按原交易标识核查，避免重试重复计入笔数。</p><label style="margin-top:16px">[原型演示] 本次核查结果<select id="lookup"><option value="missing">确认 CA 未受理，按原标识补送</option><option value="accepted">CA 已受理，读取评估结果，不重复发送</option><option value="unknown">仍无法确定，暂不补送</option></select></label>`,`<button data-action="close">取消</button><button class="primary" data-action="confirm-resend" data-id="${t.id}">执行核查结果</button>`);}
function confirmResend(id){const t=db.transactions.find(t=>t.id===id);if(!t||t.send!=='上送失败')return;const result=$('lookup').value;if(result==='unknown'){t.logs.unshift(now()+' · '+ME+' · 受理结果仍未知，未补送');save();closeModal();toast('已记录核查结果，等待进一步确认');return;}if(result==='accepted'){t.send='已上送';t.evaluation='PENDING';t.receipt='CA-DEMO-RECOVERED';t.error='';t.logs.unshift(now()+' · '+ME+' · 核查已受理，仅修正本地状态');save();closeModal();renderTransactions();toast('已更新为已上送，未重复发送');return;}const fail=failNext();t.send='上送中';t.logs.unshift(now()+' · '+ME+' · 确认未受理，使用原交易标识补送');save();closeModal();renderTransactions();setTimeout(()=>{t.send=fail?'上送失败':'已上送';t.error=fail?'补送超时，需再次核查受理结果':'';t.receipt='';t.evaluation=fail?'暂未获取':'PENDING';t.logs.unshift(now()+' · '+ME+' · '+(fail?'补送失败':'补送完成'));save();renderTransactions();toast(fail?'补送失败，请核查后重试':'补送成功，交易条数保持不变');},650);}

function canEdit(c){return !!c&&c.biz!=='Card'&&!c.pending&&c.owner===ME&&((PEOPLE[ME]==='初审'&&['调查中','待补充'].includes(c.state))||(PEOPLE[ME]==='合规'&&c.state==='合规复核中'));}
function allowed(c,a){if(!c||c.biz==='Card'||c.pending||c.state==='已结案')return false;const r=PEOPLE[ME];if(a==='claim')return r==='初审'&&c.state==='未开始'&&!c.owner;if(a==='start')return r==='初审'&&c.state==='未开始'&&c.owner===ME;if(a==='accept')return r==='合规'&&c.state==='待合规接收'&&c.initialOwner!==ME;if(a==='transfer')return r==='管理员'&&!!c.owner;return canEdit(c)&&decisions(c).includes(a);}
function decisions(c){if(c.state==='待补充')return ['补充完成，提交复核'];if(c.state==='合规复核中')return ['复核无异常，结案','确认可疑，结案','退回补充'];if(c.state==='调查中')return ['未发现异常，结案','升级合规'];return [];}
function nextStep(c){if(c.biz==='Card')return '拟议场景，当前仅查看资金时间线。';if(c.pending)return '操作待确认；保留原阶段和负责人，由提交人或管理员核查并重试。';return ({'未开始':c.owner?'由 '+c.owner+' 开始调查。':'初审人员领取后开始调查。','调查中':'由 '+c.owner+' 核查证据，提交结案或升级合规。','待合规接收':'等待合规人员接收；初审已提交，不能自行结案。','合规复核中':'由 '+c.owner+' 独立复核，可退回补充或提交最终结论。','待补充':'由 '+c.owner+' 补充调查后交回 '+c.reviewer+' 复核，不能直接结案。','已结案':'流程已结束，记录只读；新证据由合规在 CA 处理重开后回传。'})[c.state];}
function flowButtons(c){return [['claim','领取案件'],['start','开始调查'],['accept','接收并开始复核'],['transfer','转派负责人']].filter(([a])=>allowed(c,a)).map(([a,t])=>`<button class="primary" data-action="${a}" data-id="${c.id}">${t}</button>`).join('');}
function flowPanel(c){return `<section class="panel"><h2>处理进度与下一步</h2><p>待领取 → 初审调查 → 普通结案 / 升级合规 → 合规复核 → 最终结案</p><p class="sub">合规退回 → 初审补充 → 原合规人员继续复核</p><p class="notice">${esc(nextStep(c))}</p><dl class="kv"><div><dt>初审人员</dt><dd>${c.initialOwner||'待领取'}</dd></div><div><dt>合规复核人员</dt><dd>${c.reviewer||'待接收'}</dd></div><div><dt>当前责任归属</dt><dd>${c.owner||c.queue+'公共队列'}</dd></div></dl></section>`;}
let flowRequest=null;
function flowDialog(c,a,text=''){if(!allowed(c,a))return;const labels={claim:'领取案件',start:'开始调查',accept:'接收并开始复核',transfer:'转派负责人'};const title=labels[a]||a;flowRequest={id:c.id,action:a,text};const role=c.state==='合规复核中'?'合规':'初审';const choices=Object.keys(PEOPLE).filter(n=>PEOPLE[n]===role&&n!==c.owner);modal(title,`<p>案件：${esc(c.id)}</p><p>当前：${esc(c.state)} · ${esc(c.owner||c.queue+'公共队列')}</p><p>${a==='accept'?'接收后由你负责合规复核。':a==='升级合规'?'提交后进入合规公共队列，等待接收。':a==='退回补充'?'退回初审人员 '+esc(c.initialOwner)+'，保留你为复核人员。':a==='补充完成，提交复核'?'交回原合规复核人员 '+esc(c.reviewer)+'。':'确认后按该操作更新案件。'}</p>${a==='transfer'?`<label>新负责人<select id="assignee">${choices.map(n=>`<option>${n}</option>`).join('')}</select></label><label>转派原因<textarea id="transferReason"></textarea></label>`:''}<p class="sub">操作确认前保留当前状态；不执行交易或资金处置。</p><div id="flowError" class="error"></div>`,`<button data-action="close">取消</button><button class="primary" data-action="confirm-flow">确认提交</button>`);}
function confirmFlow(){if(!flowRequest)return;const {id,action:a,text}=flowRequest,c=getCase(id);if(!allowed(c,a))return;let patch={};if(a==='claim')patch={owner:ME,initialOwner:ME};else if(a==='start')patch={state:'调查中'};else if(a==='accept')patch={state:'合规复核中',owner:ME,reviewer:ME,queue:'合规'};else if(a==='transfer'){const owner=$('assignee').value,reason=$('transferReason').value.trim(),role=c.state==='合规复核中'?'合规':'初审';if(!reason||PEOPLE[owner]!==role||owner===c.owner){$('flowError').textContent='请选择同角色的新负责人并填写转派原因。';return;}patch={owner};if(role==='合规')patch.reviewer=owner;else patch.initialOwner=owner;flowRequest.text=reason;}else if(a==='升级合规')patch={state:'待合规接收',owner:'',queue:'合规',supervised:true,draft:'',conclusion:a};else if(a==='退回补充')patch={state:'待补充',owner:c.initialOwner,queue:'初审',draft:'',conclusion:a};else if(a==='补充完成，提交复核')patch={state:'合规复核中',owner:c.reviewer,queue:'合规',draft:'',conclusion:a};else patch={state:'已结案',draft:'',conclusion:a};c.pending={actor:ME,action:a,patch,text:flowRequest.text};flowRequest=null;closeModal();runSync(c);}
function refreshFlow(){if(document.body.dataset.page==='detail')detailPage();else if(document.body.dataset.page==='cases')casePage();}
document.addEventListener('change',e=>{if(e.target.id==='actor'){if(db.cases.some(c=>c.sync==='提交中')){e.target.value=ME;toast('请等待当前提交结束');return;}ME=e.target.value;localStorage.setItem('tm-actor',ME);location.reload();}});

shell();const initializers={index:indexPage,cases:casePage,detail:detailPage,transactions:transactionPage};initializers[document.body.dataset.page]();
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;switch(a){case 'close':closeModal();break;case 'prev':page--;renderList();break;case 'next':page++;renderList();break;case 'clear':$('filters').reset();page=1;renderList();break;case 'all-cases':$('filters').reset();page=1;renderCases();break;case 'claim':claim(id);break;case 'confirm-claim':confirmClaim(id);break;case 'start':flowDialog(activeCase,'start');break;case 'accept':flowDialog(activeCase,'accept');break;case 'transfer':flowDialog(activeCase,'transfer');break;case 'confirm-flow':confirmFlow();break;case 'evaluation':{const t=db.transactions.find(t=>t.id===id);t.evaluation='ALLOW';t.logs.unshift(now()+' · 查询 CA 评估结果：ALLOW（演示，不能据此推定没有案件）');save();txDetail(id);break;}case 'draft':draft();break;case 'submit':submit();break;case 'confirm-submit':finishSubmit();break;case 'sync-retry':runSync(activeCase);break;case 'tx':txDetail(id);break;case 'resend':resend(id);break;case 'confirm-resend':confirmResend(id);break;case 'reset-demo':modal('重置演示数据','<p>清除本原型的调查草稿、领取与补送记录，恢复初始虚构样例。</p>','<button data-action="close">取消</button><button class="primary" data-action="confirm-reset">确认重置</button>');break;case 'confirm-reset':db=seed();save();location.reload();break;}});
document.addEventListener('keydown',e=>{if(!$('overlay').classList.contains('active'))return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const nodes=[...$('overlay').querySelectorAll('button:not(:disabled),a,input,select,textarea')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('storage',e=>{if(e.key===KEY){toast('演示数据已在其他页面更新，请刷新后继续');}});
save();
